import React, {
  ChangeEvent,
  FocusEvent,
  forwardRef,
  KeyboardEvent,
  RefObject,
  SyntheticEvent,
  useImperativeHandle,
  useRef,
} from 'react';
import { useIntl } from 'react-intl';
import styled from 'styled-components';

import { CalendarIcon } from '@dynatrace/strato-icons';

import { DatePickerOverlay } from './DatePickerOverlay.js';
import { useDatepicker } from './hooks/useDatepicker.js';
import type { DatePickerValue } from './types/change-event.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { FormControlStateProps } from '../../core/types/form-control-state.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { useOverlayWithTrigger } from '../../overlays/hooks/useOverlayWithTrigger.js';
import { _useFormFieldContext } from '../forms-core/hooks/useFormFieldContext.js';
import type {
  FormControlRef,
  FormControlWithOverlayRef,
} from '../shared-types.js';
import { TextInput } from '../text-input/TextInput.js';

// #region Typings
export interface DatePickerProps
  extends FormControlStateProps,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * The actual value of the datepicker (controlled).
   * It is used for initializing the parsed time and rendering the display value.
   * @defaultValue null
   */
  value: string | null;
  /** The id of the datepicker text input. */
  id?: string;
  /** The name of the datepicker text input. */
  name?: string;
  /**
   * Disables the whole date picker.
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * Whether a date has to be selected before the date picker can be closed.
   * @defaultValue false
   */
  required?: boolean;
  /**
   * Whether the time is shown (in addition to the date) in the datepicker input.
   * @defaultValue false
   */
  showTime?: boolean;
  /**
   * Used to flatten the time to day-start (if false) or day-end (if true) when
   * a date is selected from the calendar. If undefined, the time is preserved
   * and not flattened.
   * @defaultValue undefined
   */
  fillUpTime?: boolean;
  /** Reference of the overlay trigger button. */
  buttonRef?: RefObject<HTMLButtonElement>;
  /**
   * The precision of the time shown in the display value.
   * @defaultValue 'seconds'
   */
  precision?: 'minutes' | 'seconds';
  /** Callback triggered when the datepicker value changes (controlled). */
  onChange: (value: DatePickerValue) => void;
  /** Callback triggered when the datepicker input is blurred. */
  onInputBlur?: (event: FocusEvent<HTMLInputElement>) => void;
  /** Callback triggered when the datepicker input value changes. */
  onInputValueChange?: (
    value: string,
    event?: ChangeEvent<HTMLInputElement>,
  ) => void;
  /** Callback triggered when the calendar value changes. */
  onCalendarValueChange?: (date: string | null, event?: SyntheticEvent) => void;
}
// #endregion

// #region StyledComponents
const StyledDatePicker = /* @__PURE__ */ styled('div')({
  display: 'inline',
});
// #endregion

/**
 * The `DatePicker` component allows users to choose a specific
 * date from a calendar or enter it via keyboard.
 */
export const DatePicker = /* @__PURE__ */ forwardRef<
  FormControlWithOverlayRef,
  DatePickerProps
>((props, forwardedRef) => {
  const {
    id: propId,
    value = null,
    showTime = false,
    disabled: propDisabled,
    required: propRequired,
    fillUpTime,
    controlState,
    buttonRef,
    onChange,
    onInputBlur,
    onCalendarValueChange: onCalendarValueChangeProp,
    onInputValueChange: onInputValueChangeProp,
    'data-testid': dataTestId,
    name,
    className: consumerClassName,
    style: consumerStyle,
    precision = 'seconds',
    ...remainingProps
  }: DatePickerProps = props;

  const ariaProps = _useAriaLabelingProps(remainingProps);

  const { controlId, disabled: contextDisabled } = _useFormFieldContext();

  const id = propId || controlId;
  const disabled = propDisabled || contextDisabled;
  // we don't need to dispatch and update the context values if the propId/propDisabled change, because the TextInput already does it and would otherwise compete with each other and could run into an infinite rendering loop

  const {
    calendarValue,
    inputValue,
    onCalendarValueChange,
    onInputValueChange,
    validateAndApplyValue,
  } = useDatepicker({ value, showTime, fillUpTime, onChange, precision });

  const {
    targetRef,
    triggerRef,
    overlayRef,
    overlayProps,
    overlayState,
    overlayTriggerProps,
    overlayContainerProps,
  } = useOverlayWithTrigger({
    placement: 'bottom-end',
    placementFallbacks: ['bottom-start', 'bottom-end', 'top-start', 'top-end'],
    offset: 8,
    disabled,
    trapFocus: true,
    heightStrategy: 'maxViewport',
  });

  // We need to create a ref to give access to the trigger in our imperative handle.
  const imperativeTriggerRef = useRef<HTMLButtonElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useImperativeHandle(
    forwardedRef,
    (): FormControlWithOverlayRef => ({
      element: containerRef.current,
      triggerRef: imperativeTriggerRef.current,
      open: overlayState.open,
      close: overlayState.close,
      focus() {
        containerRef.current?.querySelector('input')?.focus();
      },
    }),
    [overlayState.close, overlayState.open],
  );

  if (disabled && overlayState.isOpen) {
    overlayState.close();
  }

  /** Handle key down events. */
  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      validateAndApplyValue();
    }
  }

  const intl = useIntl();
  const inputButtonRef = useMergeRefs([buttonRef, triggerRef]);

  const triggerTranslation = intl.formatMessage({
    defaultMessage: 'Datepicker trigger',
    id: 'T5zhPZXEPNlTDG+I',
    description: 'Text shown in the datepicker trigger',
  });

  const textInputRef = (node: FormControlRef<HTMLDivElement>) =>
    // using the wrapper element directly here would cause the gap between the hint and the input to be added to the
    // overlay offset, so we need to target its first child, which is the flex element wrapping the input container
    node?.element && targetRef(node.element.firstElementChild as HTMLElement);

  return (
    <StyledDatePicker
      data-testid={dataTestId}
      ref={containerRef}
      className={consumerClassName}
      style={consumerStyle}
    >
      <TextInput
        ref={textInputRef}
        id={id}
        name={name}
        data-testid="date-picker-input"
        placeholder={
          showTime
            ? `yyyy-mm-dd hh:mm${precision === 'seconds' ? ':ss' : ''}`
            : 'yyyy-mm-dd'
        }
        value={inputValue}
        autoComplete="off"
        onBlur={(event: FocusEvent<HTMLInputElement>) => {
          onInputBlur?.(event);
          validateAndApplyValue();
        }}
        onChange={(value: string) => {
          onInputValueChange(value);
          onInputValueChangeProp?.(value);
        }}
        onKeyDown={handleKeyDown}
        disabled={propDisabled}
        required={propRequired}
        controlState={controlState}
        {...ariaProps}
      >
        <TextInput.Suffix>
          <TextInput.Button
            ref={inputButtonRef}
            tooltipText={triggerTranslation}
            aria-label={triggerTranslation}
            {...overlayTriggerProps}
          >
            <CalendarIcon />
          </TextInput.Button>
        </TextInput.Suffix>
      </TextInput>
      {overlayState.isOpen && (
        <DatePickerOverlay
          value={calendarValue}
          ref={overlayRef}
          overlayContainerProps={overlayContainerProps}
          overlayProps={overlayProps}
          overlayState={overlayState}
          onChange={(date: string | null) => {
            onCalendarValueChange(date);
            onCalendarValueChangeProp?.(date);
          }}
        />
      )}
    </StyledDatePicker>
  );
});

(DatePicker as typeof DatePicker & { displayName: string }).displayName =
  'DatePicker';
